package com.cpf.batch.centercut.runner; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/internal/v1/center-cut") public class CenterCutControlController { private final CenterCutRuntime r;public CenterCutControlController(CenterCutRuntime r){this.r=r;} @PostMapping("/drain") ResponseEntity<Void> drain(){r.drain();return ResponseEntity.accepted().build();} @PostMapping("/resume") ResponseEntity<Void> resume(){r.resume();return ResponseEntity.accepted().build();} }